package docker

import "testing"

// parseSize only ever sees Docker's decimal SI formatting ("1.23GB"), because its
// call sites are `docker image ls {{.Size}}`, `docker system df -v` and the
// NetIO/BlockIO columns of `docker stats` — all of which go through
// units.HumanSize. Binary units (MiB/GiB) come from MemUsage, which is formatted
// elsewhere and never reaches this function.
func TestParseSize(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want int64
	}{
		{"empty string", "", 0},
		{"bytes", "512B", 512},
		{"zero bytes", "0B", 0},
		{"kilobytes", "10.2kB", 10200},
		{"megabytes", "256MB", 256_000_000},
		{"gigabytes", "1.5GB", 1_500_000_000},
		{"fractional kilobytes", "1.2kB", 1200},
		{"surrounding whitespace is trimmed", "  64MB  ", 64_000_000},
		{"gigabytes take precedence over the bare B suffix", "2GB", 2_000_000_000},
		{"unknown unit yields zero", "5TB", 0},
		{"binary unit is not decoded", "1.5GiB", 0},
		{"non-numeric value yields zero", "abcMB", 0},
		{"missing unit yields zero", "1024", 0},
		{"embedded space breaks parsing", "1.5 GB", 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := parseSize(tt.in); got != tt.want {
				t.Errorf("parseSize(%q) = %d, want %d", tt.in, got, tt.want)
			}
		})
	}
}

func TestParseNetIO(t *testing.T) {
	tests := []struct {
		name   string
		in     string
		wantRx int64
		wantTx int64
	}{
		{"typical docker stats NetIO column", "1.2kB / 3.4kB", 1200, 3400},
		{"no whitespace around the separator", "500B/1kB", 500, 1000},
		{"zero traffic", "0B / 0B", 0, 0},
		{"mixed units", "1.5GB / 256MB", 1_500_000_000, 256_000_000},
		{"missing separator yields zeroes", "1.2kB", 0, 0},
		{"empty string yields zeroes", "", 0, 0},
		{"unparsable operands yield zeroes", "n/a", 0, 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rx, tx := parseNetIO(tt.in)
			if rx != tt.wantRx || tx != tt.wantTx {
				t.Errorf("parseNetIO(%q) = (%d, %d), want (%d, %d)", tt.in, rx, tx, tt.wantRx, tt.wantTx)
			}
		})
	}
}

package registrymgr

import "testing"

func TestParseNexusURL(t *testing.T) {
	tests := []struct {
		name     string
		in       string
		wantHost string
		wantRepo string
		wantErr  bool
	}{
		{
			name:     "canonical https repository URL",
			in:       "https://nexus.example.com/repository/docker-group",
			wantHost: "https://nexus.example.com",
			wantRepo: "docker-group",
		},
		{
			name:     "scheme defaults to https when omitted",
			in:       "nexus.example.com/repository/docker-group",
			wantHost: "https://nexus.example.com",
			wantRepo: "docker-group",
		},
		{
			name:     "explicit http scheme and port are preserved",
			in:       "http://nexus.local:8081/repository/docker-hosted",
			wantHost: "http://nexus.local:8081",
			wantRepo: "docker-hosted",
		},
		{
			name:     "trailing registry path after the repository name is ignored",
			in:       "https://nexus.example.com/repository/docker-group/v2/_catalog",
			wantHost: "https://nexus.example.com",
			wantRepo: "docker-group",
		},
		{
			name:     "trailing slash after the repository name",
			in:       "https://nexus.example.com/repository/docker-group/",
			wantHost: "https://nexus.example.com",
			wantRepo: "docker-group",
		},
		{
			name:    "a plain registry URL is not a Nexus repository",
			in:      "https://registry.example.com/v2/",
			wantErr: true,
		},
		{
			name:    "repository path with no repository name",
			in:      "https://nexus.example.com/repository/",
			wantErr: true,
		},
		{
			name:    "host without a path",
			in:      "https://nexus.example.com",
			wantErr: true,
		},
		{
			name:    "empty input",
			in:      "",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			host, repo, err := parseNexusURL(tt.in)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("parseNexusURL(%q) = (%q, %q, nil), want an error", tt.in, host, repo)
				}
				return
			}
			if err != nil {
				t.Fatalf("parseNexusURL(%q) returned unexpected error: %v", tt.in, err)
			}
			if host != tt.wantHost || repo != tt.wantRepo {
				t.Errorf("parseNexusURL(%q) = (%q, %q), want (%q, %q)", tt.in, host, repo, tt.wantHost, tt.wantRepo)
			}
		})
	}
}

