// Package testutil provides helpers for driving Bubble Tea models in tests.
//
// The views in this project are testable without a terminal because of two
// properties the codebase already guarantees:
//
//   - Constructors are pure. New(cfg) performs no I/O; Docker and network calls
//     are issued from Init() as tea.Cmd values.
//   - Update() is a pure function (Model, Msg) -> (Model, Cmd). Rule 110 forbids
//     mutating the model inside a Cmd, so feeding synthetic messages to Update()
//     fully determines the resulting state.
//
// These helpers therefore build messages and drain commands; they never spin up
// a tea.Program.
package testutil

import (
	tea "github.com/charmbracelet/bubbletea"
)

// namedKeys maps the key names used throughout the views (they all dispatch on
// tea.KeyMsg.String()) onto the key types that render back to those names.
var namedKeys = map[string]tea.KeyType{
	"enter":     tea.KeyEnter,
	"esc":       tea.KeyEsc,
	"escape":    tea.KeyEscape,
	"up":        tea.KeyUp,
	"down":      tea.KeyDown,
	"left":      tea.KeyLeft,
	"right":     tea.KeyRight,
	"tab":       tea.KeyTab,
	"shift+tab": tea.KeyShiftTab,
	" ":         tea.KeySpace,
	"space":     tea.KeySpace,
	"backspace": tea.KeyBackspace,
	"delete":    tea.KeyDelete,
	"home":      tea.KeyHome,
	"end":       tea.KeyEnd,
	"pgup":      tea.KeyPgUp,
	"pgdown":    tea.KeyPgDown,
	"ctrl+a":    tea.KeyCtrlA,
	"ctrl+c":    tea.KeyCtrlC,
	"ctrl+d":    tea.KeyCtrlD,
	"ctrl+k":    tea.KeyCtrlK,
	"ctrl+n":    tea.KeyCtrlN,
	"ctrl+o":    tea.KeyCtrlO,
	"ctrl+r":    tea.KeyCtrlR,
	"ctrl+s":    tea.KeyCtrlS,
	"ctrl+w":    tea.KeyCtrlW,
}

// Key builds the tea.KeyMsg whose String() equals name.
//
// Names listed in namedKeys map to their dedicated key type ("enter", "esc",
// "ctrl+s", " "). Anything else is treated as literal runes, so Key("y") and
// Key("gg") produce the rune messages a view matching on those strings expects.
func Key(name string) tea.KeyMsg {
	if kt, ok := namedKeys[name]; ok {
		return tea.KeyMsg{Type: kt}
	}
	return tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune(name)}
}

// Keys builds one message per name, for feeding a sequence to Update().
func Keys(names ...string) []tea.Msg {
	msgs := make([]tea.Msg, 0, len(names))
	for _, n := range names {
		msgs = append(msgs, Key(n))
	}
	return msgs
}

// Type builds one rune message per character of s, reproducing a user typing
// into a text input. Use this instead of Key(s) when the target is a
// bubbles/textinput: it consumes runes one keypress at a time.
func Type(s string) []tea.Msg {
	msgs := make([]tea.Msg, 0, len(s))
	for _, r := range s {
		msgs = append(msgs, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
	}
	return msgs
}

// Resize builds the window size message views use to lay themselves out.
func Resize(width, height int) tea.Msg {
	return tea.WindowSizeMsg{Width: width, Height: height}
}

// Msgs executes cmd and returns every message it produced, flattening the
// tea.Batch tree. A nil command, or one returning nil, yields no messages.
//
// The command runs synchronously on the calling goroutine. Do not pass a command
// that sleeps or performs I/O — tea.Tick blocks for its whole duration, and the
// Docker runners shell out. Assert on the command's identity or on model state
// instead for those.
func Msgs(cmd tea.Cmd) []tea.Msg {
	if cmd == nil {
		return nil
	}
	msg := cmd()
	if msg == nil {
		return nil
	}
	if batch, ok := msg.(tea.BatchMsg); ok {
		var out []tea.Msg
		for _, c := range batch {
			out = append(out, Msgs(c)...)
		}
		return out
	}
	return []tea.Msg{msg}
}

// Msg executes cmd and returns the single message it produced, or nil.
// It is the common case of Msgs for commands that emit exactly one message.
func Msg(cmd tea.Cmd) tea.Msg {
	msgs := Msgs(cmd)
	if len(msgs) == 0 {
		return nil
	}
	return msgs[0]
}

// MsgOf reports whether cmd produced a message of type T, returning the first
// such message. It searches through batched commands.
func MsgOf[T tea.Msg](cmd tea.Cmd) (T, bool) {
	for _, m := range Msgs(cmd) {
		if v, ok := m.(T); ok {
			return v, true
		}
	}
	var zero T
	return zero, false
}

package testutil

import (
	"testing"

	tea "github.com/charmbracelet/bubbletea"
)

// The views dispatch on tea.KeyMsg.String(). If Key() ever stopped round-tripping
// through that method, every Update() test built on this harness would silently
// exercise the default branch instead of the intended one — so the round-trip is
// asserted here rather than assumed.
func TestKeyRoundTripsThroughString(t *testing.T) {
	names := []string{
		"enter", "esc", "up", "down", "left", "right",
		"tab", "shift+tab", " ", "backspace", "delete",
		"home", "end", "pgup", "pgdown",
		"ctrl+a", "ctrl+c", "ctrl+d", "ctrl+k", "ctrl+n",
		"ctrl+o", "ctrl+r", "ctrl+s", "ctrl+w",
	}

	for _, name := range names {
		t.Run(name, func(t *testing.T) {
			if got := Key(name).String(); got != name {
				t.Errorf("Key(%q).String() = %q, want %q", name, got, name)
			}
		})
	}
}

func TestKeyAliases(t *testing.T) {
	if got := Key("space").String(); got != " " {
		t.Errorf(`Key("space").String() = %q, want " "`, got)
	}
	if got := Key("escape").String(); got != "esc" {
		t.Errorf(`Key("escape").String() = %q, want "esc"`, got)
	}
}

func TestKeyRunes(t *testing.T) {
	tests := []string{"y", "n", "Y", "N", "q", "j", "k", "gg", "/"}
	for _, s := range tests {
		t.Run(s, func(t *testing.T) {
			msg := Key(s)
			if msg.Type != tea.KeyRunes {
				t.Errorf("Key(%q).Type = %v, want KeyRunes", s, msg.Type)
			}
			if got := msg.String(); got != s {
				t.Errorf("Key(%q).String() = %q, want %q", s, got, s)
			}
		})
	}
}

func TestKeysBuildsOneMessagePerName(t *testing.T) {
	msgs := Keys("up", "down", "enter")
	if len(msgs) != 3 {
		t.Fatalf("Keys() returned %d messages, want 3", len(msgs))
	}
	want := []string{"up", "down", "enter"}
	for i, m := range msgs {
		km, ok := m.(tea.KeyMsg)
		if !ok {
			t.Fatalf("message %d is %T, want tea.KeyMsg", i, m)
		}
		if km.String() != want[i] {
			t.Errorf("message %d = %q, want %q", i, km.String(), want[i])
		}
	}
}

// Type must emit one keypress per rune: a textinput consumes runes one message
// at a time, so a single multi-rune message would be dropped or mis-parsed.
func TestTypeEmitsOneKeypressPerRune(t *testing.T) {
	msgs := Type("abc")
	if len(msgs) != 3 {
		t.Fatalf("Type(\"abc\") returned %d messages, want 3", len(msgs))
	}
	for i, want := range []string{"a", "b", "c"} {
		km := msgs[i].(tea.KeyMsg)
		if len(km.Runes) != 1 {
			t.Errorf("message %d carries %d runes, want 1", i, len(km.Runes))
		}
		if km.String() != want {
			t.Errorf("message %d = %q, want %q", i, km.String(), want)
		}
	}
}

func TestTypeEmpty(t *testing.T) {
	if msgs := Type(""); len(msgs) != 0 {
		t.Errorf("Type(\"\") returned %d messages, want 0", len(msgs))
	}
}

func TestResize(t *testing.T) {
	msg, ok := Resize(120, 40).(tea.WindowSizeMsg)
	if !ok {
		t.Fatalf("Resize() returned %T, want tea.WindowSizeMsg", msg)
	}
	if msg.Width != 120 || msg.Height != 40 {
		t.Errorf("Resize(120, 40) = %dx%d, want 120x40", msg.Width, msg.Height)
	}
}

type msgAlpha struct{ n int }
type msgBeta struct{}

func TestMsgsNilCommand(t *testing.T) {
	if got := Msgs(nil); got != nil {
		t.Errorf("Msgs(nil) = %v, want nil", got)
	}
}

func TestMsgsCommandReturningNil(t *testing.T) {
	cmd := func() tea.Msg { return nil }
	if got := Msgs(cmd); got != nil {
		t.Errorf("Msgs() = %v, want nil for a command producing no message", got)
	}
}

func TestMsgsSingleCommand(t *testing.T) {
	cmd := func() tea.Msg { return msgAlpha{n: 7} }
	msgs := Msgs(cmd)
	if len(msgs) != 1 {
		t.Fatalf("Msgs() returned %d messages, want 1", len(msgs))
	}
	if got, ok := msgs[0].(msgAlpha); !ok || got.n != 7 {
		t.Errorf("Msgs()[0] = %#v, want msgAlpha{n:7}", msgs[0])
	}
}

// tea.Batch nests commands one level; tea.Batch of a tea.Batch nests further.
// Msgs must flatten the whole tree, otherwise a batched message would be
// reported as an opaque BatchMsg.
func TestMsgsFlattensNestedBatches(t *testing.T) {
	inner := tea.Batch(
		func() tea.Msg { return msgAlpha{n: 2} },
		func() tea.Msg { return msgBeta{} },
	)
	cmd := tea.Batch(
		func() tea.Msg { return msgAlpha{n: 1} },
		inner,
	)

	msgs := Msgs(cmd)
	if len(msgs) != 3 {
		t.Fatalf("Msgs() returned %d messages, want 3", len(msgs))
	}
	for _, m := range msgs {
		if _, isBatch := m.(tea.BatchMsg); isBatch {
			t.Fatal("Msgs() leaked a tea.BatchMsg instead of flattening it")
		}
	}
}

func TestMsgReturnsFirstOrNil(t *testing.T) {
	if got := Msg(nil); got != nil {
		t.Errorf("Msg(nil) = %v, want nil", got)
	}
	cmd := func() tea.Msg { return msgBeta{} }
	if _, ok := Msg(cmd).(msgBeta); !ok {
		t.Errorf("Msg() = %T, want msgBeta", Msg(cmd))
	}
}

func TestMsgOfFindsTypeInBatch(t *testing.T) {
	cmd := tea.Batch(
		func() tea.Msg { return msgAlpha{n: 42} },
		func() tea.Msg { return msgBeta{} },
	)

	got, ok := MsgOf[msgAlpha](cmd)
	if !ok {
		t.Fatal("MsgOf[msgAlpha]() did not find the message")
	}
	if got.n != 42 {
		t.Errorf("MsgOf[msgAlpha]().n = %d, want 42", got.n)
	}

	if _, ok := MsgOf[msgBeta](cmd); !ok {
		t.Error("MsgOf[msgBeta]() did not find the message")
	}
}

func TestMsgOfAbsentType(t *testing.T) {
	cmd := func() tea.Msg { return msgBeta{} }
	if _, ok := MsgOf[msgAlpha](cmd); ok {
		t.Error("MsgOf[msgAlpha]() reported a message that was never produced")
	}
	if _, ok := MsgOf[msgAlpha](nil); ok {
		t.Error("MsgOf[msgAlpha](nil) reported a message")
	}
}

package components

import (
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"

	"gitlab.com/anthnell/devsecops/devdesk/internal/ui/testutil"
)

// Rule 104 requires the safe choice to be preselected on destructive
// confirmations. A regression here silently arms "Yes" under the cursor.
func TestNewConfirmModalDefaultsToNo(t *testing.T) {
	m := NewConfirmModal("Delete", "Delete this monitor?")
	if m.focused {
		t.Error("NewConfirmModal() focused Yes; the safe default is No")
	}
}

func TestConfirmModalArrowsToggleSelection(t *testing.T) {
	for _, key := range []string{"left", "right"} {
		t.Run(key, func(t *testing.T) {
			m := NewConfirmModal("Delete", "Sure?")

			m, cmd := m.Update(testutil.Key(key))
			if !m.focused {
				t.Errorf("after %q, selection did not move to Yes", key)
			}
			if cmd != nil {
				t.Errorf("after %q, expected no command, got one", key)
			}

			m, _ = m.Update(testutil.Key(key))
			if m.focused {
				t.Errorf("after a second %q, selection did not move back to No", key)
			}
		})
	}
}

func TestConfirmModalEnterAndSpaceConfirmSelection(t *testing.T) {
	tests := []struct {
		name    string
		key     string
		focused bool
		wantYes bool
	}{
		{"enter on No", "enter", false, false},
		{"enter on Yes", "enter", true, true},
		{"space on No", " ", false, false},
		{"space on Yes", " ", true, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := NewConfirmModal("Delete", "Sure?")
			m.focused = tt.focused

			_, cmd := m.Update(testutil.Key(tt.key))
			assertConfirmAnswer(t, cmd, tt.wantYes)
		})
	}
}

func TestConfirmModalLetterShortcuts(t *testing.T) {
	tests := []struct {
		key     string
		wantYes bool
	}{
		{"y", true},
		{"Y", true},
		{"n", false},
		{"N", false},
		{"esc", false},
	}

	for _, tt := range tests {
		t.Run(tt.key, func(t *testing.T) {
			m := NewConfirmModal("Delete", "Sure?")

			_, cmd := m.Update(testutil.Key(tt.key))
			assertConfirmAnswer(t, cmd, tt.wantYes)
		})
	}
}

// The letter shortcuts must answer regardless of which button is highlighted,
// otherwise "n" on a focused Yes would confirm a deletion.
func TestConfirmModalLetterShortcutsIgnoreSelection(t *testing.T) {
	m := NewConfirmModal("Delete", "Sure?")
	m.focused = true // Yes is highlighted

	_, cmd := m.Update(testutil.Key("n"))
	assertConfirmAnswer(t, cmd, false)
}

func TestConfirmModalIgnoresUnhandledKeys(t *testing.T) {
	m := NewConfirmModal("Delete", "Sure?")

	got, cmd := m.Update(testutil.Key("z"))
	if cmd != nil {
		t.Error("an unhandled key produced a command")
	}
	if got.focused {
		t.Error("an unhandled key changed the selection")
	}
}

func TestConfirmModalStoresWindowSize(t *testing.T) {
	m := NewConfirmModal("Delete", "Sure?")

	m, _ = m.Update(testutil.Resize(120, 40))
	if m.width != 120 || m.height != 40 {
		t.Errorf("window size = %dx%d, want 120x40", m.width, m.height)
	}
}

func TestConfirmModalViewShowsTitleAndMessage(t *testing.T) {
	m := NewConfirmModal("Delete monitor", "This cannot be undone")

	view := m.View()
	for _, want := range []string{"Delete monitor", "This cannot be undone", "Yes", "No"} {
		if !strings.Contains(view, want) {
			t.Errorf("View() does not contain %q", want)
		}
	}
}

// assertConfirmAnswer drains cmd and checks which answer message it carries.
func assertConfirmAnswer(t *testing.T, cmd tea.Cmd, wantYes bool) {
	t.Helper()

	if cmd == nil {
		t.Fatal("expected an answer command, got nil")
	}
	_, gotYes := testutil.MsgOf[ConfirmModalYesMsg](cmd)
	_, gotNo := testutil.MsgOf[ConfirmModalNoMsg](cmd)

	switch {
	case wantYes && !gotYes:
		t.Errorf("expected ConfirmModalYesMsg, got %T", testutil.Msg(cmd))
	case !wantYes && !gotNo:
		t.Errorf("expected ConfirmModalNoMsg, got %T", testutil.Msg(cmd))
	}
}

package components

import (
	"strings"
	"testing"

	"gitlab.com/anthnell/devsecops/devdesk/internal/ui/testutil"
)

// Rule 136: the bar is completely hidden until a filter is actually active.
func TestFilterBarHiddenUntilFiltered(t *testing.T) {
	fb := NewFilterBar()

	if fb.IsVisible() {
		t.Error("a fresh FilterBar reports itself visible")
	}
	if got := fb.ExtraHeight(); got != 0 {
		t.Errorf("ExtraHeight() = %d on a hidden bar, want 0", got)
	}
}

func TestFilterBarVisibilityTriggers(t *testing.T) {
	t.Run("search mode makes it visible", func(t *testing.T) {
		fb := NewFilterBar()
		fb.ActivateSearch()

		if !fb.IsVisible() {
			t.Error("bar is hidden while searching")
		}
		if got := fb.ExtraHeight(); got != 2 {
			t.Errorf("ExtraHeight() = %d while visible, want 2", got)
		}
	})

	t.Run("a confirmed query keeps it visible", func(t *testing.T) {
		fb := NewFilterBar()
		fb.ActivateSearch()
		feedFilterBar(&fb, testutil.Type("web")...)
		fb.Update(testutil.Key("enter"))

		if fb.InEditMode() {
			t.Error("still in edit mode after enter")
		}
		if !fb.IsVisible() {
			t.Error("bar hidden despite a confirmed query")
		}
		if got := fb.SearchQuery(); got != "web" {
			t.Errorf("SearchQuery() = %q, want %q", got, "web")
		}
	})

	t.Run("an active token makes it visible", func(t *testing.T) {
		fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}, {Label: "udp"}})
		if fb.IsVisible() {
			t.Error("bar visible with no active token")
		}

		fb.SetTokenActive("tcp", true)
		if !fb.IsVisible() {
			t.Error("bar hidden despite an active token")
		}
	})
}

func TestFilterBarActivateSearchEntersEditMode(t *testing.T) {
	fb := NewFilterBar()

	if fb.InEditMode() {
		t.Error("a fresh FilterBar is already in edit mode")
	}
	cmd := fb.ActivateSearch()
	if !fb.InEditMode() {
		t.Error("ActivateSearch() did not enter edit mode")
	}
	if cmd == nil {
		t.Error("ActivateSearch() returned no blink command")
	}
}

func TestFilterBarTypingUpdatesQueryLive(t *testing.T) {
	fb := NewFilterBar()
	fb.ActivateSearch()

	feedFilterBar(&fb, testutil.Type("eth")...)

	if got := fb.SearchQuery(); got != "eth" {
		t.Errorf("SearchQuery() = %q while typing, want %q", got, "eth")
	}
}

func TestFilterBarEscapeDiscardsQuery(t *testing.T) {
	fb := NewFilterBar()
	fb.ActivateSearch()
	feedFilterBar(&fb, testutil.Type("discard me")...)

	fb.Update(testutil.Key("esc"))

	if fb.InEditMode() {
		t.Error("still in edit mode after esc")
	}
	if got := fb.SearchQuery(); got != "" {
		t.Errorf("SearchQuery() = %q after esc, want empty", got)
	}
	if fb.IsVisible() {
		t.Error("bar still visible after esc discarded the query")
	}
}

// Update must ignore keys unless the bar owns them, otherwise a view forwarding
// every keypress would swallow its own shortcuts.
func TestFilterBarIgnoresKeysWhenNotSearching(t *testing.T) {
	fb := NewFilterBar()

	fb.Update(testutil.Key("a"))

	if got := fb.SearchQuery(); got != "" {
		t.Errorf("SearchQuery() = %q after a key outside search mode, want empty", got)
	}
	if fb.IsVisible() {
		t.Error("bar became visible from a key outside search mode")
	}
}

func TestFilterBarIgnoresNonKeyMessages(t *testing.T) {
	fb := NewFilterBar()
	fb.ActivateSearch()

	fb.Update(testutil.Resize(100, 30))

	if !fb.InEditMode() {
		t.Error("a window resize dropped the bar out of edit mode")
	}
}

func TestFilterBarClearSearch(t *testing.T) {
	fb := NewFilterBar()
	fb.ActivateSearch()
	feedFilterBar(&fb, testutil.Type("query")...)

	fb.ClearSearch()

	if fb.InEditMode() || fb.SearchQuery() != "" || fb.IsVisible() {
		t.Errorf("ClearSearch() left state behind: editing=%v query=%q visible=%v",
			fb.InEditMode(), fb.SearchQuery(), fb.IsVisible())
	}
}

func TestFilterBarTokenToggling(t *testing.T) {
	fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}, {Label: "udp"}})

	if fb.IsTokenActive("tcp") {
		t.Error("token starts active")
	}
	fb.SetTokenActive("tcp", true)
	if !fb.IsTokenActive("tcp") {
		t.Error("SetTokenActive(true) had no effect")
	}
	if fb.IsTokenActive("udp") {
		t.Error("activating tcp also activated udp")
	}
	fb.SetTokenActive("tcp", false)
	if fb.IsTokenActive("tcp") {
		t.Error("SetTokenActive(false) had no effect")
	}
}

func TestFilterBarUnknownTokenIsInert(t *testing.T) {
	fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}})

	fb.SetTokenActive("nope", true)

	if fb.IsTokenActive("nope") {
		t.Error("an unknown label reports as active")
	}
	if fb.IsVisible() {
		t.Error("setting an unknown label made the bar visible")
	}
}

// SetTokens is called on every refresh of a live table; losing the active state
// there would silently reset the user's filter under them.
func TestSetTokensPreservesActiveStateByLabel(t *testing.T) {
	fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}, {Label: "udp"}})
	fb.SetTokenActive("tcp", true)

	fb.SetTokens([]FilterToken{{Label: "udp"}, {Label: "tcp"}, {Label: "raw"}})

	if !fb.IsTokenActive("tcp") {
		t.Error("SetTokens() dropped the active state of tcp")
	}
	if fb.IsTokenActive("udp") || fb.IsTokenActive("raw") {
		t.Error("SetTokens() activated a token that was not active before")
	}
}

func TestSetTokensDropsRemovedLabels(t *testing.T) {
	fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}})
	fb.SetTokenActive("tcp", true)

	fb.SetTokens([]FilterToken{{Label: "udp"}})

	if fb.IsTokenActive("tcp") {
		t.Error("a token absent from the new list is still reported active")
	}
	if fb.IsVisible() {
		t.Error("bar still visible after its only active token disappeared")
	}
}

// The bar draws a closed rectangle that joins the viewport's bottom border,
// so both lines must span exactly the configured width.
func TestFilterBarViewFormsClosedRectangle(t *testing.T) {
	fb := NewFilterBarWithTokens([]FilterToken{{Label: "tcp"}})
	fb.SetTokenActive("tcp", true)
	fb.Resize(40)

	lines := strings.Split(fb.View(), "\n")
	if len(lines) != 2 {
		t.Fatalf("View() produced %d lines, want 2", len(lines))
	}
	if !strings.Contains(lines[1], "└") || !strings.Contains(lines[1], "┘") {
		t.Errorf("bottom line is not a closed border: %q", lines[1])
	}
	if !strings.Contains(lines[0], "tcp") {
		t.Error("active token is missing from the rendered bar")
	}
}

func TestFilterBarViewFallsBackToDefaultWidth(t *testing.T) {
	fb := NewFilterBar()
	fb.ActivateSearch()

	lines := strings.Split(fb.View(), "\n")
	if len(lines) != 2 {
